<div class="two-col">
<section class="panel">
<div class="panel-head"><div><h2>Thành viên dự án</h2><p><?= count($members) ?> thành viên trong dự án đang chọn · <?= count($workspaceMembers) ?> tài khoản trong các dự án bạn quản lý</p></div></div>
