<?php else: ?>
<div class="member-head"><span class="avatar"><?= e(strtoupper(substr($workspaceMember['name'],0,2))) ?></span><div><strong><?= e($workspaceMember['name']) ?></strong><small><?= e($workspaceMember['email'] ?: ('Tên đăng nhập: '.($workspaceMember['username']??''))) ?></small></div><?php if($member): ?><span class="pill <?= $member['role']==='admin'?'green':'gray' ?>"><?= e($member['role']) ?></span><a class="button small" href="<?= e(url('audit')) ?>&amp;actor_user_id=<?= (int)$member['user_id'] ?>">Xem Log</a><?php if($member['role']!=='admin'): ?><form method="post" action="<?= e(url('members/audit-permission')) ?>"><?= csrf_field() ?><input type="hidden" name="membership_id" value="<?= (int)$member['id'] ?>"><button class="button small" type="submit"><?= $member['can_view_audit']?'Thu hồi quyền xem Log':'Cho phép xem Log' ?></button></form><?php endif; ?><?php else: ?><span class="pill gray">Chưa tham gia dự án này</span><?php endif; ?></div>
<?php endif; ?>
<?php if(count($memberProjects)>1 && $memberId!==(int)$user['id']): ?>
<form method="post" action="<?= e(url('members/projects')) ?>" class="subproject-form project-access-form"><?= csrf_field() ?><input type="hidden" name="member_id" value="<?= $memberId ?>"><strong>Dự án được phép truy cập</strong><div class="permission-features"><?php foreach($memberProjects as $project): $assignedRole=$assignments[(int)$project['id']]??null; ?><label><input type="checkbox" name="project_ids[]" value="<?= (int)$project['id'] ?>" <?= $assignedRole!==null?'checked':'' ?> <?= $assignedRole==='admin'?'disabled':'' ?>><span><?= e($project['name']) ?><?php if($assignedRole): ?> <code><?= e($assignedRole) ?></code><?php endif; ?></span><?php if($assignedRole==='admin'): ?><input type="hidden" name="project_ids[]" value="<?= (int)$project['id'] ?>"><?php endif; ?></label><?php endforeach; ?></div><button class="button small" type="submit">Lưu dự án</button></form>
<?php endif; ?>
<?php if (!$member): ?>
<p class="muted">Tài khoản này đang ở dự án khác. Chọn dự án ở trên để cấp quyền tham gia.</p>
<?php elseif (($member['role']??'')==='child'): ?>
<form method="post" action="<?= e(url('subaccounts/permissions')) ?>" class="subproject-form"><?= csrf_field() ?><input type="hidden" name="child_id" value="<?= (int)$member['user_id'] ?>"><input type="hidden" name="permission_project_id" value="<?= (int)$projectId ?>"><strong>Features được phép bật/tắt trong dự án hiện tại</strong><?php if(!$flags): ?><p class="empty">Dự án chưa có feature.</p><?php else: ?><div class="permission-features"><?php foreach($flags as $flag): ?><label><input type="checkbox" name="flag_ids[]" value="<?= (int)$flag['id'] ?>" <?= in_array((int)$flag['id'],$subaccountPermissions[(int)$member['user_id']][(int)$projectId]??[],true)?'checked':'' ?>><span><?= e($flag['name']) ?> <code><?= e($flag['key']) ?></code></span></label><?php endforeach; ?></div><?php endif; ?><button class="button small" type="submit">Lưu quyền Feature</button></form>
<?php elseif (($member['role']??'')!=='admin'): ?>
<form method="post" action="<?= e(url('members/permissions')) ?>" class="subproject-form"><?= csrf_field() ?><input type="hidden" name="membership_id" value="<?= (int)$member['id'] ?>"><div class="permission-grid"><label>Vai trò<select name="role" data-editor-role><option value="viewer" <?= $member['role']==='viewer'?'selected':'' ?>>Viewer</option><option value="editor" <?= $member['role']==='editor'?'selected':'' ?>>Editor</option></select></label><label class="check-label"><input type="checkbox" name="can_view_audit" <?= $member['can_view_audit']?'checked':'' ?>> Xem audit log</label></div><div data-editor-fields<?= $member['role']==='viewer'?' hidden':'' ?>><p class="muted">Editor chỉ sửa được feature được chọn.</p><div class="flag-permissions"><?php foreach($flags as $flag): ?><label><input type="checkbox" name="flag_ids[]" value="<?= (int)$flag['id'] ?>" <?= in_array((int)$flag['id'],$permissions[$member['id']]??[],true)?'checked':'' ?>> <?= e($flag['key']) ?></label><?php endforeach; ?></div></div><button class="button small" type="submit">Lưu phân quyền</button></form>
<?php else: ?><p class="muted">Quản trị viên toàn quyền trong dự án.</p><?php endif; ?>
</article>
<?php endforeach; endif; ?>
</section>
<section class="panel"><div class="panel-head"><div><h2>Tạo tài khoản</h2><p>Nhập thông tin và chọn dự án trước. Vai trò sẽ hiện sau khi chọn dự án.</p></div></div><form method="post" action="<?= e(url('members/create')) ?>" class="form-grid" id="accountCreateForm"><?= csrf_field() ?><label class="check-label wide"><input type="checkbox" name="can_view_audit"> Cho phép xem audit log</label><label>Họ tên<input name="name" required maxlength="160"></label><label>Email<input name="email" id="accountEmail" type="email" autocomplete="email"></label><?php if($projects): ?><label data-managed hidden>Tên đăng nhập<input name="username" id="accountUsername" minlength="3" maxlength="80" pattern="[A-Za-z0-9][A-Za-z0-9_.-]{2,79}" autocomplete="username"></label><?php endif; ?><label class="wide">Mật khẩu tạm (tối thiểu 8 ký tự)<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><?php if($projects): ?><div class="wide"><strong>Dự án được phép truy cập</strong><p class="muted">Chọn một hoặc nhiều dự án để cấp quyền truy cập.</p><div class="permission-features"><?php foreach($projects as $project): ?><label><input type="checkbox" name="project_ids[]" value="<?= (int)$project['id'] ?>" data-project-choice><span><?= e($project['name']) ?> <code><?= e($project['key']) ?></code></span></label><?php endforeach; ?></div></div><div class="wide" data-managed-role hidden><label>Vai trò<select name="managed_role" id="managedRole"><option value="viewer">Viewer</option><option value="editor">Editor</option></select></label></div><?php foreach($projects as $project): ?><div class="wide" data-project-features="<?= (int)$project['id'] ?>" hidden><strong>Features được phép bật/tắt · <?= e($project['name']) ?></strong><div class="permission-features"><?php foreach($managedFeatures[(int)$project['id']] ?? [] as $feature): ?><label><input type="checkbox" name="project_flag_ids[<?= (int)$project['id'] ?>][]" value="<?= (int)$feature['id'] ?>"><span><?= e($feature['name']) ?> <code><?= e($feature['key']) ?></code></span></label><?php endforeach; ?></div></div><?php endforeach; ?><?php endif; ?><div data-member-fields class="wide"><label>Vai trò<select name="role" data-editor-role><option value="viewer">Viewer</option><option value="editor">Editor</option></select></label><div data-editor-fields hidden><strong>Features được sửa (dành cho Editor)</strong><div class="flag-permissions"><?php foreach($flags as $flag): ?><label><input type="checkbox" name="flag_ids[]" value="<?= (int)$flag['id'] ?>"> <?= e($flag['key']) ?></label><?php endforeach; ?></div></div></div><button class="button primary" type="submit">Tạo tài khoản</button></form><script>(function(){var checks=document.querySelectorAll('[data-project-choice]'),email=document.getElementById('accountEmail'),username=document.getElementById('accountUsername'),managed=document.querySelector('[data-managed]'),managedRole=document.querySelector('[data-managed-role]'),roleSelect=document.getElementById('managedRole'),memberFields=document.querySelector('[data-member-fields]');function update(){var selected=Array.from(checks).filter(function(box){return box.checked;}).map(function(box){return box.value;}),assigned=selected.length>0,isEditor=roleSelect&&roleSelect.value==='editor';if(managed)managed.hidden=!assigned;if(managedRole)managedRole.hidden=!assigned;if(memberFields)memberFields.hidden=assigned;if(email)email.required=!assigned;if(username)username.required=assigned;document.querySelectorAll('[data-project-features]').forEach(function(group){group.hidden=!assigned||!isEditor||selected.indexOf(group.dataset.projectFeatures)===-1;});}checks.forEach(function(box){box.addEventListener('change',update);});if(roleSelect)roleSelect.addEventListener('change',update);document.querySelectorAll('[data-editor-role]').forEach(function(select){var fields=select.closest('form').querySelector('[data-editor-fields]');function toggleEditorFields(){if(fields)fields.hidden=select.value!=='editor';}select.addEventListener('change',toggleEditorFields);toggleEditorFields();});update();})();</script></section></div>
